package com.example.directory;

import javax.naming.NamingEnumeration;
import javax.naming.NamingException;
import javax.naming.directory.DirContext;
import javax.naming.directory.SearchControls;
import javax.naming.directory.SearchResult;

public class DirectoryService {
    private static final String BASE = "ou=people,dc=example,dc=com";
    private final DirContext ctx;

    public DirectoryService(DirContext ctx) {
        this.ctx = ctx;
    }

    private static String uidFilter(String uid) {
        return "(uid=" + uid.trim() + ")";
    }

    public NamingEnumeration<SearchResult> findUser(String uid) throws NamingException {
        SearchControls controls = new SearchControls();
        controls.setSearchScope(SearchControls.SUBTREE_SCOPE);
        return ctx.search(BASE, uidFilter(uid), controls);
    }
}
